L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP13_ACT1_PROLOGUE1@10#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 579
L17_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "SIMURGH_NPC_NULL_NULL"
L17_1.m_Talk_KOREA = "부정. 연합 역시 멸망을 피하기 위해, 동원할 수 있는 모든 연산을 동원했습니다."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "否定。連合もまた滅亡を避けるために、できる限りの演算を算出しました。"
L17_1.m_Talk_ENG = "Negative. The Interstellar Alliance had also run every possible calculation to avoid devastation."
L17_1.m_Talk_TWN = "否定。為了避免滅亡，聯盟也動用了一切可以動用的資源。"
L17_1.m_Talk_SCN = "否定。为了避免灭亡，联盟也动用了一切可以动用的资源。"
L17_1.m_Talk_DEU = "Negative. The Interstellar Alliance had also run every possible calculation to avoid devastation."
L17_1.m_Talk_FRA = "Negative. The Interstellar Alliance had also run every possible calculation to avoid devastation."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP13_ACT1_PROLOGUE1@11#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 579
L18_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "SIMURGH_NPC_NULL_NULL"
L18_1.m_Talk_KOREA = "아시모프께서는 유기체가 감당할 수 없는 긴 세월 동안, 그 문제만을 연산하셨습니다."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "アシモフは有機体が耐えられないほど長い期間、その問題の演算を繰り返しておられました。"
L18_1.m_Talk_ENG = "Asimov had calculated this problem for a time longer than an organism can handle."
L18_1.m_Talk_TWN = "阿西莫夫在這個問題上花費了相當長的時間，比生物體能夠處理的時間還要長。"
L18_1.m_Talk_SCN = "阿西莫夫在这个问题上花费了相当长的时间，比生物体能够处理的时间还要长。"
L18_1.m_Talk_DEU = "Asimov had calculated this problem for a time longer than an organism can handle."
L18_1.m_Talk_FRA = "Asimov had calculated this problem for a time longer than an organism can handle."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP13_ACT1_PROLOGUE1@12#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 579
L19_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "SIMURGH_NPC_NULL_NULL"
L19_1.m_Talk_KOREA = "재차 부정. 엄정하신 기계 장치의 신께서 내린 결론을 부정할 셈입니까?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "再度否定。厳正なる機械装置の神が下した結論を否定するつもりですか？"
