L22_1.m_CharStrID = "CAT_YAKSHA_NULL_NULL"
L22_1.m_Talk_KOREA = "세계가 어쩌고, 멸망이 어쩌고, 신이 어쩌고 그딴 와닿지도 않는 이야기! 알 바 아니라고!"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "世界がどうの、滅亡がどうの、神がどうの。そんな話、知ったことじゃないんだよ！"
L22_1.m_Talk_ENG = "All this mumbo-jumbo about the world ending and whatever gods! That's none of my business!"
L22_1.m_Talk_TWN = "世界也好，毀滅也好，還有你們的神也好，這些虛無縹緲的事情！和我有什麼關係！"
L22_1.m_Talk_SCN = "世界也好，毁灭也好，还有你们的神也好，这些虚无缥缈的事情！和我有什么关系！"
L22_1.m_Talk_DEU = "All this mumbo-jumbo about the world ending and whatever gods! That's none of my business!"
L22_1.m_Talk_FRA = "All this mumbo-jumbo about the world ending and whatever gods! That's none of my business!"
