L47_1 = "<color=#ff3636>警告！移民舰西摩格，主驱动器严重损坏。</color>"
L46_1.m_Talk_SCN = L47_1
L47_1 = "<color=#ff3636>Warning. Exodus Fleet Simurgh... Critical damage to the main drive.</color>"
