L31_1 = "ASIMOV_QLIPHOTH_NPC_QM"
L30_1.m_CharStrID = L31_1
L31_1 = "정해진 사건을 뒤틀지 않고, 또다시 세계로부터 <color=#ffd34c>변화</color>를 이끌어냈으니까요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "決められた事件を捻じ曲げることなく、再び世界に<color=#ffd34c>変化</color>をもたらしたのですから。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You once again brought about <color=#ffd34c>change</color> in this world, without disrupting the events already set in motion."
L30_1.m_Talk_ENG = L31_1
L31_1 = "沒有扭曲既定的事件，再次從世界中引出了<color=#ffd34c>變化</color>。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "没有扭曲既定的事件，再次从世界中引出了<color=#ffd34c>变化</color>。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "You once again brought about <color=#ffd34c>change</color> in this world, without disrupting the events already set in motion."
L30_1.m_Talk_DEU = L31_1
L31_1 = "You once again brought about <color=#ffd34c>change</color> in this world, without disrupting the events already set in motion."
