L43_1 = "연합의 레거시 데이터에 따르면, 인류가 최초로 이곳에 접촉한 것은 1969년의 아폴로 계획."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "m_bTalkCenterFadeIn"
L42_1[L43_1] = true
L43_1 = "連合のレガシーデータによると、人類が初めてこの場所に降り立ったのは1969年のアポロ計画の時。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "According to the Alliance's legacy data, humanity first made contact with this site during the Apollo Program in 1969."
