L42_1.m_Talk_TWN = L43_1
L43_1 = "根据联盟战纪数据，人类首次接触此地是在1969年的阿波罗计划。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "According to the Alliance's legacy data, humanity first made contact with this site during the Apollo Program in 1969."
