L44_1 = "달을 조사하던 저궤도 탐사선의 선원들이 정체불명의 소리를 듣게 된 것이 그 시작이었다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "m_bTalkCenterFadeIn"
L43_1[L44_1] = true
L44_1 = "月を調査していた低軌道探査船の船員たちの耳に、正体不明の音声が届いたことがその始まりだった。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It all began when the crew of a low-orbit lunar probe heard an unidentified sound."
L43_1.m_Talk_ENG = L44_1
L44_1 = "調查月球的低軌道探測船的船員們聽到了不明聲音，這就是事情的開端。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "调查月球的低轨道探测船的船员们听到了不明声音，这就是事情的开端。"
