L44_1.m_fTalkTime = 0.03
L45_1 = "m_bTalkCenterFadeIn"
L44_1[L45_1] = true
L45_1 = "大気が存在しない月の裏側から聞こえてくる、聞こえるはずのない奇妙な歌声。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "A strange song, echoing from the dark side of the moon, where no atmosphere exists... and no sound should be heard."
