L49_1 = "성간이동이 가능해진 인류는 달과 관련된 몇 가지 사실을 밝혀낸다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "m_bTalkCenterFadeIn"
L48_1[L49_1] = true
L49_1 = "星間移動が可能になった人類は、月に関わるいくつかの新事実を突き止める。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "With interstellar travel now within humanity's reach, several truths about the moon have come to light."
L48_1.m_Talk_ENG = L49_1
L49_1 = "能夠進行星際移動的人類揭示了一些與月球相關的事實。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "能够进行星际移动的人类揭示了一些与月球相关的事实。"
