L50_1 = "첫째. 달 탐사를 통해 입수한 월석에서 강력한 에너지 파장의 흔적이 검출되었다는 것."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "m_bTalkCenterFadeIn"
L49_1[L50_1] = true
L50_1 = "その1。月の探査を通じて入手した月の石から、強力なエネルギーの痕跡が検出されたこと。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "First, traces of a powerful energy wavelength were detected in lunar rock samples collected during exploration."
L49_1.m_Talk_ENG = L50_1
L50_1 = "第一，透過月球探測獲得的月石中檢測到了強烈的能量波動。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "第一，通过月球探测获得的月石中检测到了强烈的能量波动。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "First, traces of a powerful energy wavelength were detected in lunar rock samples collected during exploration."
L49_1.m_Talk_DEU = L50_1
L50_1 = "First, traces of a powerful energy wavelength were detected in lunar rock samples collected during exploration."
L49_1.m_Talk_FRA = L50_1
