L50_1.m_CutScenID = 579
L50_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "둘째. 해당 에너지 파장의 발생 시점이 물질계 발생 시점과 거의 일치한다는 것."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "m_bTalkCenterFadeIn"
L50_1[L51_1] = true
L51_1 = "その2。そのエネルギーの発生時点が物質界の発生時点とほぼ一致すること。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Second, the origin point of this energy wavelength closely matches the birth of the material realm."
