L2_1 = "その3。そのエネルギーの波長を分析した結果、カウンターのCRF波長と類似したパターンを持っていたこと。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Third, analysis of the energy wavelength revealed that the pattern closely resembles that of the CRF wavelength of Counters."
