L10_1.m_BGOffsetScale = L11_1
L11_1 = "그것은 <color=#ffd34c>세피로트 나무</color> 가설."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "m_bTalkCenterFadeIn"
L10_1[L11_1] = true
L11_1 = "それは<color=#ffd34c>セフィロト</color>の仮説である。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "It's the <color=#ffd34c>Tree of Sephiroth</color> hypothesis."
L10_1.m_Talk_ENG = L11_1
L11_1 = "那是<color=#ffd34c>生命樹</color>假說。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "那是<color=#ffd34c>塞菲罗特之树</color>假说。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "It's the <color=#ffd34c>Tree of Sephiroth</color> hypothesis."
L10_1.m_Talk_DEU = L11_1
L11_1 = "It's the <color=#ffd34c>Tree of Sephiroth</color> hypothesis."
L10_1.m_Talk_FRA = L11_1
