L12_1 = "EP13_ACT1_PROLOGUE1@106#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 579
L11_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "이 세계는 마치 나무의 가지처럼, 수없이 많은 평행 세계로 분화되어 있으며."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "m_bTalkCenterFadeIn"
L11_1[L12_1] = true
L12_1 = "この世界はまるで木の枝のように、数多のパラレルワールドに分かれており。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "A hypothesis that this world, like the branches of a great tree, has splintered into countless parallel dimensions."
L11_1.m_Talk_ENG = L12_1
L12_1 = "這個世界就像樹枝一樣，分化成無數個平行世界。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "这个世界就像树枝一样，分化成无数个平行世界。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "A hypothesis that this world, like the branches of a great tree, has splintered into countless parallel dimensions."
L11_1.m_Talk_DEU = L12_1
L12_1 = "A hypothesis that this world, like the branches of a great tree, has splintered into countless parallel dimensions."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP13_ACT1_PROLOGUE1@107#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 579
L12_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "무수히 분화된 다차원의 평행 세계가 결국 하나의 뿌리로부터 출발했으리라는 가설."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "m_bTalkCenterFadeIn"
L12_1[L13_1] = true
L13_1 = "無数に分かれた多次元のパラレルワールドは結局、ひとつの根から始まっているという仮説。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "And that all these divergent, multi-dimensional worlds can be traced back to a single root."
L12_1.m_Talk_ENG = L13_1
L13_1 = "無數分化的多次元平行世界最後都源自一個根源的假設。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "无数分化的多维平行世界最终都源自一个根源的假设。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "And that all these divergent, multi-dimensional worlds can be traced back to a single root."
L12_1.m_Talk_DEU = L13_1
L13_1 = "And that all these divergent, multi-dimensional worlds can be traced back to a single root."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP13_ACT1_PROLOGUE1@108#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 579
L13_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "그 뿌리는 태초에 물질계를 현현시킨 <color=#ffd34c>신성</color>의 작용이자."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "m_bTalkCenterFadeIn"
L13_1[L14_1] = true
L14_1 = "その根は、原初の時に物質界を顕現させた<color=#ffd34c>神聖</color>の作用であり、"
L13_1.m_Talk_JPN = L14_1
L14_1 = "That root is the <color=#ffd34c>Divinity</color> that first gave form to the material world."
L13_1.m_Talk_ENG = L14_1
L14_1 = "其根源是最初顯現在物質界的<color=#ffd34c>神聖</color>作用。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "其根源是最初显现在物质界的<color=#ffd34c>神圣</color>作用。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "That root is the <color=#ffd34c>Divinity</color> that first gave form to the material world."
L13_1.m_Talk_DEU = L14_1
L14_1 = "That root is the <color=#ffd34c>Divinity</color> that first gave form to the material world."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP13_ACT1_PROLOGUE1@109#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 579
L14_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "현실개변력의 총체라고 할 수 있는 모든 가능성의 <color=#ffd34c>근원</color>."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "m_bTalkCenterFadeIn"
L14_1[L15_1] = true
L15_1 = "現実改変力の総体とも言うべき、あらゆる可能性の<color=#ffd34c>根源</color>。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "It's the <color=#ffd34c>origin</color> of all possibilities, and the foundation of what we call the Counter Reality Force."
L14_1.m_Talk_ENG = L15_1
L15_1 = "可以說是現實變革力的總和，一切可能性的<color=#ffd34c>根源</color>。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "可以说是现实变革力的总和，一切可能性的<color=#ffd34c>根源</color>。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "It's the <color=#ffd34c>origin</color> of all possibilities, and the foundation of what we call the Counter Reality Force."
L14_1.m_Talk_DEU = L15_1
L15_1 = "It's the <color=#ffd34c>origin</color> of all possibilities, and the foundation of what we call the Counter Reality Force."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP13_ACT1_PROLOGUE1@110#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 579
L15_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "연합은 그것을 세계를 만드는 법칙.\n<color=#ffd34c>세피로트 나무</color>라고 불렀다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "m_bTalkCenterFadeIn"
L15_1[L16_1] = true
L16_1 = "連合はそれを世界を作る法則、\n<color=#ffd34c>セフィロト</color>と呼んだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = [[
The Alliance named it the law of creating a world.
In other words, the <color=#ffd34c>Tree of Sephiroth</color>.]]
L15_1.m_Talk_ENG = L16_1
L16_1 = "聯盟稱其為創造世界的法則。\n<color=#ffd34c>名為生命樹</color>。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "联盟称其为创造世界的法则。\n<color=#ffd34c>名为塞菲罗特之树</color>。"
L15_1.m_Talk_SCN = L16_1
L16_1 = [[
The Alliance named it the law of creating a world.
In other words, the <color=#ffd34c>Tree of Sephiroth</color>.]]
L15_1.m_Talk_DEU = L16_1
L16_1 = [[
The Alliance named it the law of creating a world.
