L21_1 = "EP13_ACT1_PROLOGUE1@111#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 579
L20_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "세피로트 나무 가설에 근거.\n연합은 그것에 다다르기 위해 수단과 방법을 가리지 않았다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "m_bTalkCenterFadeIn"
L20_1[L21_1] = true
L21_1 = "セフィロトの仮説に基づき、\n連合はそれに至るためにあらゆる手段を講じた。"
L20_1.m_Talk_JPN = L21_1
L21_1 = [[
Based on the Tree of Sephiroth Hypothesis,
the Alliance stopped at nothing to reach it.]]
L20_1.m_Talk_ENG = L21_1
L21_1 = "基於生命樹假說。\n聯盟為了達到那個目標，不擇手段。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "基于塞菲罗特之树假说。\n联盟为了达到那个目标，不择手段。"
L20_1.m_Talk_SCN = L21_1
L21_1 = [[
Based on the Tree of Sephiroth Hypothesis,
the Alliance stopped at nothing to reach it.]]
L20_1.m_Talk_DEU = L21_1
L21_1 = [[
Based on the Tree of Sephiroth Hypothesis,
the Alliance stopped at nothing to reach it.]]
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP13_ACT1_PROLOGUE1@112#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 579
L21_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "인류의 구제를 위해."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "m_bTalkCenterFadeIn"
L21_1[L22_1] = true
L22_1 = "人類の救済のために。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "To save humanity."
L21_1.m_Talk_ENG = L22_1
L22_1 = "為了拯救人類。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "为了拯救人类。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "To save humanity."
L21_1.m_Talk_DEU = L22_1
L22_1 = "To save humanity."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP13_ACT1_PROLOGUE1@113#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 579
L22_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "침식으로부터 안전한 곳을 찾기 위해."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "m_bTalkCenterFadeIn"
L22_1[L23_1] = true
L23_1 = "侵食の脅威から逃れられる、安全な場所を探すために。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "To find a haven untouched by Corruption."
L22_1.m_Talk_ENG = L23_1
L23_1 = "為了尋找一個免受侵蝕的安全地方。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "为了寻找一个免受侵蚀的安全地方。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "To find a haven untouched by Corruption."
L22_1.m_Talk_DEU = L23_1
L23_1 = "To find a haven untouched by Corruption."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP13_ACT1_PROLOGUE1@114#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 579
L23_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "이제는 들려올 리 없는, 달의 노래가 들려오는 곳으로 향하기 위해."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "m_bTalkCenterFadeIn"
L23_1[L24_1] = true
L24_1 = "もはや聞こえるはずもない、月の歌が聞こえる場所をめざして。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "To reach the place where the moon's song can be still heard, though it should be impossible."
L23_1.m_Talk_ENG = L24_1
L24_1 = "為了前往那不再受月之歌聲侵擾的地方。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "为了前往那不再受月之歌声侵扰的地方。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "To reach the place where the moon's song can be still heard, though it should be impossible."
L23_1.m_Talk_DEU = L24_1
L24_1 = "To reach the place where the moon's song can be still heard, though it should be impossible."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP13_ACT1_PROLOGUE1@115#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 579
L24_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "이미 모성조차 상실해 버린 연합은 오랜 시간, 수많은 세계를 떠돌며 달의 뒷면을 탐사했다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "m_bTalkCenterFadeIn"
L24_1[L25_1] = true
L25_1 = "すでに母星すら失った連合は、長年にわたって数多の世界を巡り月の裏側を探査した。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "With their homeworld already gone, the Alliance scoured the dark side of the moon, endlessly drifting from world to world through the ages."
L24_1.m_Talk_ENG = L25_1
L25_1 = "已經失去母性的聯盟，長時間在無數世界中漂泊，探索著月球的背面。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "已经失去母性的联盟，长时间在无数世界中漂泊，探索着月球的背面。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "With their homeworld already gone, the Alliance scoured the dark side of the moon, endlessly drifting from world to world through the ages."
L24_1.m_Talk_DEU = L25_1
L25_1 = "With their homeworld already gone, the Alliance scoured the dark side of the moon, endlessly drifting from world to world through the ages."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP13_ACT1_PROLOGUE1@116#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 579
L25_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "그러나 세피로트 나무의 존재는 어디까지나 가설의 영역."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "m_bTalkCenterFadeIn"
L25_1[L26_1] = true
L26_1 = "しかしセフィロトの存在はあくまで仮説の領域。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "However, the Tree of Sephiroth remained within the realm of hypothesis."
L25_1.m_Talk_ENG = L26_1
L26_1 = "不過生命樹的存在只是一個假設。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "不过塞菲罗特之树的存在只是一个假设。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "However, the Tree of Sephiroth remained within the realm of hypothesis."
L25_1.m_Talk_DEU = L26_1
L26_1 = "However, the Tree of Sephiroth remained within the realm of hypothesis."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP13_ACT1_PROLOGUE1@117#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 579
L26_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "이미 오래전에 소멸해버린 차원 균열에 다다르는 것은\n유한한 생명을 가진 이들에게는 불가능에 가까운 일."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "m_bTalkCenterFadeIn"
L26_1[L27_1] = true
L27_1 = "とうの昔に消滅している次元の亀裂に至ることは\n限りある命を持つ者にとっては不可能に近い。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Reaching a dimensional rift that vanished long ago is an almost impossible task for those bound by mortal lifespans."
L26_1.m_Talk_ENG = L27_1
L27_1 = "對於生命有限的人來說，抵達早已消失的次元裂縫幾乎是不可能的事。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "对于生命有限的人来说，抵达早已消失的次元裂缝几乎是不可能的事。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Reaching a dimensional rift that vanished long ago is an almost impossible task for those bound by mortal lifespans."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Reaching a dimensional rift that vanished long ago is an almost impossible task for those bound by mortal lifespans."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP13_ACT1_PROLOGUE1@118#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 579
L27_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "결국, 유기체의 필연적 한계를 극복할 수 없는 연합은 인간의 사명을 기계에게 부여한다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "m_bTalkCenterFadeIn"
L27_1[L28_1] = true
L28_1 = "結局、有機体の必然的な限界を克服できなかった連合は、人間の使命を機械に負わせた。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "In the end, unable to overcome the inherent limits of organic life, the Alliance entrusts humanity's mission to machines."
L27_1.m_Talk_ENG = L28_1
L28_1 = "最後，由於無法突破有機體的局限，聯盟將人類的使命賦予了機械。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "最终，由于无法突破有机体的局限，联盟将人类的使命赋予了机械。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "In the end, unable to overcome the inherent limits of organic life, the Alliance entrusts humanity's mission to machines."
L27_1.m_Talk_DEU = L28_1
L28_1 = "In the end, unable to overcome the inherent limits of organic life, the Alliance entrusts humanity's mission to machines."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP13_ACT1_PROLOGUE1@119#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 579
L28_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "언젠가 자신들이 만든 피조물이 낙원을 연산해낼 날을 기도하면서."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "m_bTalkCenterFadeIn"
L28_1[L29_1] = true
L29_1 = "いつか自分たちが作り出した被造物が、楽園の位置をはじき出すことを願って。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Praying for the day when their own creation would one day compute paradise into being."
L28_1.m_Talk_ENG = L29_1
L29_1 = "祈禱著有一天他們創造的物體能夠演算出樂園出現的那一天。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "祈祷着有一天他们创造的物体能够演算出乐园出现的那一天。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Praying for the day when their own creation would one day compute paradise into being."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Praying for the day when their own creation would one day compute paradise into being."
L28_1.m_Talk_FRA = L29_1
