L46_1.m_Talk_SCN = L47_1
L47_1 = "...Captain."
L46_1.m_Talk_DEU = L47_1
L47_1 = "...Captain."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP13_ACT1_PROLOGUE1@131#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 579
L47_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "당신도 알다시피, 이 세계의 모든 것은 인과율에 의해 철저히 조율되고 있습니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "あなたもご存知のように、この世界の全ては因果律により徹底的に調整されています。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "As you already know, every aspect of this world is finely tuned by the laws of causality."
L47_1.m_Talk_ENG = L48_1
L48_1 = "你也知道，這個世界上的一切都被因果律嚴格地調節著。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "您也知道，这个世界上的一切都被因果律严格地调控着。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "As you already know, every aspect of this world is finely tuned by the laws of causality."
L47_1.m_Talk_DEU = L48_1
L48_1 = "As you already know, every aspect of this world is finely tuned by the laws of causality."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP13_ACT1_PROLOGUE1@132#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 579
L48_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "이에 따라, 모든 세계는 확실하게 멸망점을 향해 수렴하게 되어 있죠."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "これにより、全ての世界は確実に滅亡に向かって収束するようになっています。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "As a result, every world is destined to converge upon its own point of destruction."
L48_1.m_Talk_ENG = L49_1
L49_1 = "因此，所有世界都會無可避免地走向滅亡。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "因此，所有世界都会无可避免地走向灭亡。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "As a result, every world is destined to converge upon its own point of destruction."
L48_1.m_Talk_DEU = L49_1
L49_1 = "As a result, every world is destined to converge upon its own point of destruction."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP13_ACT1_PROLOGUE1@133#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 579
L49_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "성간 연합을 포함. 제가 관측했던 그 어떤 세계도 멸망을 피할 수는 없었습니다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "星間連合を含め、私が観測したどの世界も滅亡を回避することはできませんでした。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Even the Interstellar Alliance was no exception. Of all the worlds I've observed, not one escaped destruction."
L49_1.m_Talk_ENG = L50_1
L50_1 = "包括星際聯盟在內，我所觀察到的任何世界都無法避免滅亡。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "包括星际联盟在内，我所观察到的任何世界都无法避免灭亡。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Even the Interstellar Alliance was no exception. Of all the worlds I've observed, not one escaped destruction."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Even the Interstellar Alliance was no exception. Of all the worlds I've observed, not one escaped destruction."
L49_1.m_Talk_FRA = L50_1
