L3_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "멸망이 확정되어 버린 세계에서 세피라 포인트를 발견하는 것은 불가능하겠죠."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "滅亡が確定した世界でセフィラポイントを見つけることは叶わないでしょう。"
