L32_1 = "<color=#ffd34c>긴급상황 발생. 각 클리파로부터 차원 계면 융해 현상 관측. </color>"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "<color=#ffd34c>緊急事態発生。各クリファ次元より次元界面融解現象を観測。</color>"
L31_1.m_Talk_JPN = L32_1
L32_1 = "<color=#ffd34c>Emergency alert. Dimension surface dissolution detected in each Qlipha.</color>"
L31_1.m_Talk_ENG = L32_1
