L37_1.m_CharStrID = L38_1
L38_1 = "누군가 세계의 진실에 다다르게 만들 바에는, 차라리 세계 그 자체를 무너트려 버리겠다는 사고 방식."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "誰かに世界の真実に至ることを許すくらいなら、いっそ世界そのものを破壊するという思考。"
